INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',693,'{"_type":"chat:Message","id":"8641420749:1578","threadId":"telegram:8641420749","text":"Je me suis aperçu en commencant à rouler que j’ai une douleur musculaire en haut de la cuisse droite, sur l’avant, le haut du quadriceps. Je ne m’en suis pas rendu compte avant en marchant ou autre. Uniquement là en commencant à pedaler. Et ça n’est pas passé le long de ce ride. Je dirais un 3/10. Demain matin je pense faire un massage sportif pour aider. Qu’est-ce que ça peut etre ?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Je me suis aperçu en commencant à rouler que j’ai une douleur musculaire en haut de la cuisse droite, sur l’avant, le haut du quadriceps. Je ne m’en suis pas rendu compte avant en marchant ou autre. Uniquement là en commencant à pedaler. Et ça n’est pas passé le long de ce ride. Je dirais un 3/10. Demain matin je pense faire un massage sportif pour aider. Qu’est-ce que ça peut etre ?","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":387,"offset":386}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":387,"offset":386}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":387,"offset":386}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-09-04T20:01:16.000Z","edited":false},"attachments":[],"isMention":false}',1789156873936);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',694,'{"_type":"chat:Message","id":"8641420749:1584","threadId":"telegram:8641420749","text":"Oui le pic FC c’est un probleme capteur. \nPas fait le renfo ce matin, je pensais le faire ce soir mais je ne vais pas le faire vu la douleur. Donc c’est pas du à ça, c’est du aux 3 jours avec bike trailer où j’ai du vraiment forcer dans certaines montées sans pouvoir me mettre en danseuse.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Oui le pic FC c’est un probleme capteur.\nPas fait le renfo ce matin, je pensais le faire ce soir mais je ne vais pas le faire vu la douleur. Donc c’est pas du à ça, c’est du aux 3 jours avec bike trailer où j’ai du vraiment forcer dans certaines montées sans pouvoir me mettre en danseuse.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":249,"offset":290}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":249,"offset":290}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":249,"offset":290}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-09-04T20:16:56.000Z","edited":false},"attachments":[],"isMention":false}',1789157813170);
